G:{t:'Mohimi me لَا, “dua” dhe lidhja e dy emrave',h:`<h3>Mohimi i së tashmes: لَا</h3><table><tr><td class="ar">أَشْرَبُ الْقَهْوَةَ</td><td>pi kafe</td></tr><tr><td class="ar">لَا أَشْرَبُ الْقَهْوَةَ</td><td>nuk pi kafe</td></tr><tr><td class="ar">لَا يَأْكُلُ اللَّحْمَ</td><td>ai nuk ha mish</td></tr></table>
<h3>أُرِيدُ = dua</h3><p>Pas foljes, emri i pashquar merr fetha me tenvin (<span class="ar">ـً</span>): <span class="ar">أُرِيدُ مَاءً</span>, <span class="ar">أُرِيدُ خُبْزًا</span>. Me ال merr fetha: <span class="ar">أُرِيدُ الْخُبْزَ</span>.</p>
<p><span class="ar">تُرِيدُ</span> = ti (djalë) do · <span class="ar">تُرِيدِينَ</span> = ti (vajzë) do.</p>
<h3>Lidhja e dy emrave (إِضَافَة)</h3><p>Dy emra të njëpasnjëshëm: i pari pa tenvin dhe pa ال, i dyti me kesre.</p><table><tr><td class="ar">كُوبُ شَايٍ</td><td>një gotë çaj</td></tr><tr><td class="ar">عَصِيرُ تُفَّاحٍ</td><td>lëng molle</td></tr><tr><td class="ar">صَلَاةُ الْفَجْرِ</td><td>namazi i sabahut</td></tr></table>
<p class="note"><span class="ar">بِدُونِ</span> (pa) sillet si parafjalë: <span class="ar">بِدُونِ سُكَّرٍ</span>.</p>`,
ex:[{p:'“Nuk pi kafe.”',o:['لَا أَشْرَبُ الْقَهْوَةَ','لَا أَشْرَبُ الْقَهْوَةُ','أَشْرَبُ لَا الْقَهْوَةَ','لَا يَشْرَبُ الْقَهْوَةَ'],ar:1},{p:'“Dua ujë.”',o:['أُرِيدُ مَاءً','أُرِيدُ مَاءٌ','تُرِيدُ مَاءً','أُرِيدُ الْمَاءُ'],ar:1},{p:'“Një gotë çaj”',o:['كُوبُ شَايٍ','كُوبٌ شَايٌ','الْكُوبُ شَايٍ','كُوبُ شَايٌ'],ar:1},{p:'“Ai nuk ha mish.”',o:['لَا يَأْكُلُ اللَّحْمَ','لَا آكُلُ اللَّحْمَ','يَأْكُلُ اللَّحْمَ','لَا يَأْكُلُ اللَّحْمُ'],ar:1},{p:'“Ushqimi është i shijshëm.”',o:['الطَّعَامُ لَذِيذٌ','طَعَامٌ لَذِيذٌ','الطَّعَامُ لَذِيذَةٌ','الطَّعَامُ اللَّذِيذُ'],ar:1},{p:'“Çaj pa sheqer”',o:['شَايٌ بِدُونِ سُكَّرٍ','شَايٌ بِدُونِ سُكَّرٌ','شَايٌ مَعَ سُكَّرٍ','سُكَّرٌ بِدُونِ شَايٍ'],ar:1},{p:'“A do (djalë) lëng?”',o:['هَلْ تُرِيدُ عَصِيرًا؟','هَلْ أُرِيدُ عَصِيرًا؟','هَلْ تُرِيدِينَ عَصِيرًا؟','هَلْ تُرِيدُ عَصِيرٌ؟'],ar:1}]},
build:[['Dua ujë, të lutem.',['أُرِيدُ','مَاءً','مِنْ','فَضْلِكَ']],['Nuk pi kafe.',['لَا','أَشْرَبُ','الْقَهْوَةَ']],['Ushqimi është i shijshëm.',['الطَّعَامُ','لَذِيذٌ']],['Një gotë çaj pa sheqer.',['كُوبُ','شَايٍ','بِدُونِ','سُكَّرٍ']],['Jam shumë i uritur.',['أَنَا','جَائِعٌ','جِدًّا']]],
