D1:{t:'Erdhi koha e namazit',l:[['Omeri','اللَّهُ أَكْبَرُ! هَلْ تَسْمَعُ الْأَذَانَ؟','Allahu ekber! A e dëgjon ezanin?'],['Aliu','نَعَمْ، حَانَ وَقْتُ صَلَاةِ الْعَصْرِ.','Po, erdhi koha e namazit të ikindisë.'],['Omeri','هَلِ الْمَسْجِدُ قَرِيبٌ؟','A është xhamia afër?'],['Aliu','نَعَمْ، الْمَسْجِدُ قَرِيبٌ، بِجَانِبِ الْمَدْرَسَةِ.','Po, xhamia është afër, pranë shkollës.'],['Omeri','إِذَنْ نَتَوَضَّأُ ثُمَّ نَذْهَبُ مَعًا.','Atëherë marrim abdes dhe pastaj shkojmë bashkë.'],['Aliu','إِنْ شَاءَ اللَّهُ.','Inshallah.'],['Omeri','تَقَبَّلَ اللَّهُ.','(Pas namazit) Allahu e pranoftë.'],['Aliu','مِنَّا وَمِنْكُمْ.','Prej nesh dhe prej jush.']],
q:[{p:'Koha e cilit namaz erdhi?',o:['Ikindisë','Sabahut','Akshamit','Jacisë']},{p:'Ku është xhamia?',o:['Pranë shkollës','Pranë parkut','Larg','Prapa shtëpisë']},{p:'Çfarë bëjnë para se të shkojnë?',o:['Marrin abdes','Hanë drekë','Lexojnë','Flenë']},{p:'Si përgjigjesh kur të thonë تَقَبَّلَ اللَّهُ?',o:['مِنَّا وَمِنْكُمْ','وَعَلَيْكُمُ السَّلَامُ','صَبَاحُ النُّورِ','عَفْوًا'],ar:1}]},
D2:{t:'Dita e xhumasë',l:[['Ahmedi','لِمَاذَا تَذْهَبُ إِلَى الْمَسْجِدِ مُبَكِّرًا الْيَوْمَ؟','Pse po shkon herët në xhami sot?'],['Jusufi','لِأَنَّ الْيَوْمَ يَوْمُ الْجُمُعَةِ.','Sepse sot është dita e xhumasë.'],['Ahmedi','مَنْ يَذْهَبُ مَعَكَ؟','Kush vjen me ty?'],['Jusufi','أَبِي وَأَخِي. نَحْنُ نُصَلِّي الْجُمُعَةَ مَعًا كُلَّ أُسْبُوعٍ.','Babai dhe vëllai. Ne e falim xhumanë bashkë çdo javë.'],['Ahmedi','مَنِ الْإِمَامُ؟','Kush është imami?'],['Jusufi','الْإِمَامُ مُدَرِّسٌ فِي الْمَدْرَسَةِ.','Imami është mësues në shkollë.'],['Ahmedi','مَا شَاءَ اللَّهُ. أَنَا أَذْهَبُ مَعَكُمْ.','Mashallah. Vij edhe unë me ju.']],
q:[{p:'Pse shkon Jusufi herët?',o:['Sepse është xhuma','Sepse ka shkollë','Sepse është vonë','Sepse është imam']},{p:'Me kë shkon?',o:['Me babain dhe vëllain','Me nënën','Vetëm','Me mësuesin']},{p:'Kush është imami?',o:['Mësues në shkollë','Mjek','Babai i Jusufit','Student']},{p:'Çfarë do të thotë لِأَنَّ?',o:['Sepse','Pse','Atëherë','Por']}]},
G:{t:'Ne, ju, ata: نَحْنُ، أَنْتُمْ، هُمْ',h:`<p>Për shumësin, folja e tashme merr këto forma:</p>
<table><tr><td class="ar">نَحْنُ نَذْهَبُ</td><td>ne shkojmë (نَ)</td></tr><tr><td class="ar">أَنْتُمْ تَذْهَبُونَ</td><td>ju shkoni (تَ … ونَ)</td></tr><tr><td class="ar">هُمْ يَذْهَبُونَ</td><td>ata shkojnë (يَ … ونَ)</td></tr></table>
<p>Me <span class="ar">أُصَلِّي</span>: <span class="ar">نُصَلِّي، تُصَلُّونَ، يُصَلُّونَ</span>. Me <span class="ar">أَسْمَعُ</span>: <span class="ar">نَسْمَعُ، تَسْمَعُونَ، يَسْمَعُونَ</span>.</p>
<h3>Pse? Sepse…</h3><table><tr><td class="ar">لِمَاذَا تَذْهَبُ؟</td><td>Pse shkon?</td></tr><tr><td class="ar">لِأَنَّ الْيَوْمَ الْجُمُعَةُ</td><td>Sepse sot është xhuma</td></tr></table>
<h3>Të gjitha parashtesat bashkë</h3><table><tr><td class="ar">أَ</td><td>unë</td></tr><tr><td class="ar">نَ</td><td>ne</td></tr><tr><td class="ar">تَ</td><td>ti / ajo / ju (+ونَ)</td></tr><tr><td class="ar">يَ</td><td>ai / ata (+ونَ)</td></tr></table>
<p class="note">Përshëndetjet <span class="ar">السَّلَامُ عَلَيْكُمْ</span> dhe <span class="ar">مِنْكُمْ</span> përdorin “ju” edhe për një person, nga respekti.</p>`,
ex:[{p:'“Ne shkojmë në xhami.”',o:['نَحْنُ نَذْهَبُ إِلَى الْمَسْجِدِ','نَحْنُ يَذْهَبُونَ إِلَى الْمَسْجِدِ','أَنَا نَذْهَبُ إِلَى الْمَسْجِدِ','نَحْنُ تَذْهَبُ إِلَى الْمَسْجِدِ'],ar:1},{p:'“Ata falen.”',o:['هُمْ يُصَلُّونَ','هُمْ نُصَلِّي','هُمْ يُصَلِّي','نَحْنُ يُصَلُّونَ'],ar:1},{p:'“A e dëgjoni ezanin?” (ju)',o:['هَلْ تَسْمَعُونَ الْأَذَانَ؟','هَلْ نَسْمَعُ الْأَذَانَ؟','هَلْ يَسْمَعُونَ الْأَذَانَ؟','هَلْ تَسْمَعُونَ الْأَذَانُ؟'],ar:1},{p:'Cila parashtesë tregon “ne”?',o:['نَ','أَ','يَ','تَ'],ar:1},{p:'“Xhamia është afër.”',o:['الْمَسْجِدُ قَرِيبٌ','الْمَسْجِدُ قَرِيبَةٌ','مَسْجِدٌ قَرِيبٌ','الْمَسْجِدُ الْقَرِيبُ'],ar:1},{p:'Cila fjalë do të thotë “pse?”',o:['لِمَاذَا','مَاذَا','مَتَى','كَيْفَ'],ar:1},{p:'“Ne marrim abdes.”',o:['نَتَوَضَّأُ','أَتَوَضَّأُ','يَتَوَضَّئُونَ','تَتَوَضَّأُ'],ar:1}]},
build:[['Ne shkojmë në xhami.',['نَحْنُ','نَذْهَبُ','إِلَى','الْمَسْجِدِ']],['Erdhi koha e namazit.',['حَانَ','وَقْتُ','الصَّلَاةِ']],['Xhamia është afër.',['الْمَسْجِدُ','قَرِيبٌ']],['Ata e falin xhumanë.',['هُمْ','يُصَلُّونَ','الْجُمُعَةَ']],['Pse shkon herët?',['لِمَاذَا','تَذْهَبُ','مُبَكِّرًا؟']]],
