D1:{t:'Në dyqanin e rrobave',l:[['Shitësi','أَهْلًا وَسَهْلًا. مَاذَا تُرِيدُ؟','Mirë se erdhe. Çfarë dëshiron?'],['Jusufi','أُرِيدُ قَمِيصًا أَبْيَضَ.','Dua një këmishë të bardhë.'],['Shitësi','تَفَضَّلْ، هَذَا قَمِيصٌ أَبْيَضُ جَمِيلٌ.','Urdhëro, kjo është një këmishë e bardhë e bukur.'],['Jusufi','بِكَمْ هَذَا الْقَمِيصُ؟','Sa kushton kjo këmishë?'],['Shitësi','بِتِسْعَةِ رِيَالَاتٍ.','Nëntë rialë.'],['Jusufi','هَذَا غَالٍ قَلِيلًا. هَلْ عِنْدَكَ قَمِيصٌ رَخِيصٌ؟','Kjo është pak e shtrenjtë. A ke ndonjë këmishë të lirë?'],['Shitësi','نَعَمْ، هَذَا الْقَمِيصُ الْأَزْرَقُ بِسَبْعَةِ رِيَالَاتٍ.','Po, kjo këmishë e kaltër kushton shtatë rialë.'],['Jusufi','طَيِّبٌ، آخُذُهُ. تَفَضَّلْ.','Mirë, po e marr. Urdhëro.']],
q:[{p:'Çfarë dëshiron Jusufi?',o:['Një këmishë','Këpucë','Pantallona','Një libër']},{p:'Çfarë ngjyre kërkon në fillim?',o:['E bardhë','E zezë','E kaltër','E kuqe']},{p:'Sa kushton këmisha e bardhë?',o:['Nëntë rialë','Shtatë rialë','Dhjetë rialë','Pesë rialë']},{p:'Cilën këmishë merr?',o:['Të kaltrën','Të bardhën','Të zezën','Asnjërën']}]},
D2:{t:'Në treg me nënën',l:[['Nëna','نَشْتَرِي الْيَوْمَ الْخُضَارَ وَالْفَوَاكِهَ.','Sot blejmë perime dhe fruta.'],['Fatimja','كَمْ تُفَّاحَةً نَشْتَرِي يَا أُمِّي؟','Sa mollë të blejmë, nënë?'],['Nëna','نَشْتَرِي سِتَّ تُفَّاحَاتٍ وَأَرْبَعَ بُرْتُقَالَاتٍ.','Blejmë gjashtë mollë dhe katër portokaj.'],['Fatimja','بِكَمْ كِيلُو الْمَوْزِ؟','Sa kushton kilogrami i bananeve?'],['Shitësi','الْكِيلُو بِثَلَاثَةِ رِيَالَاتٍ.','Kilogrami kushton tre rialë.'],['Nëna','نَأْخُذُ كِيلُو وَاحِدًا. خُذْ عَشَرَةَ رِيَالَاتٍ.','Marrim një kilogram. Merr dhjetë rialë.'],['Shitësi','شُكْرًا. وَهَذِهِ سَبْعَةُ رِيَالَاتٍ لَكِ.','Faleminderit. Dhe këto shtatë rialë janë për ty (kusuri).']],
q:[{p:'Sa mollë blejnë?',o:['Gjashtë','Katër','Tri','Dhjetë']},{p:'Sa kushton kilogrami i bananeve?',o:['Tre rialë','Shtatë rialë','Dhjetë rialë','Gjashtë rialë']},{p:'Sa para i jep nëna shitësit?',o:['Dhjetë rialë','Tre rialë','Shtatë rialë','Pesë rialë']},{p:'Sa i kthen shitësi?',o:['Shtatë rialë','Tre rialë','Dhjetë rialë','Asgjë']}]},
G:{t:'Numrat 1–10 dhe pyetja “sa?”',h:`<p>Numrat 1 dhe 2 vijnë pas emrit, si mbiemër: <span class="ar">قَمِيصٌ وَاحِدٌ</span> (një këmishë). Numrat 3–10 vijnë para emrit, dhe emri është në shumës:</p>
<table><tr><td class="ar">ثَلَاثَةُ رِيَالَاتٍ</td><td>tre rialë</td></tr><tr><td class="ar">سَبْعَةُ كُتُبٍ</td><td>shtatë libra</td></tr></table>
<h3>Rregulli i “kundërt”</h3><p>Me 3–10, numri merr gjininë e kundërt të emrit: emër mashkullor → numër me <span class="ar">ة</span>; emër femëror → numër pa <span class="ar">ة</span>.</p>
<table><tr><td class="ar">خَمْسَةُ رِجَالٍ</td><td>pesë burra (mashkullor)</td></tr><tr><td class="ar">خَمْسُ نِسَاءٍ</td><td>pesë gra (femëror)</td></tr></table>
<h3>Sa? Sa kushton?</h3><table><tr><td class="ar">كَمْ كِتَابًا عِنْدَكَ؟</td><td>Sa libra ke? (pas كَمْ: njëjës me -an)</td></tr><tr><td class="ar">بِكَمْ هَذَا؟</td><td>Sa kushton kjo?</td></tr></table>
<h3>Ngjyrat</h3><table><tr><td class="ar">أَبْيَضُ / بَيْضَاءُ</td><td>i bardhë / e bardhë</td></tr><tr><td class="ar">أَسْوَدُ / سَوْدَاءُ</td><td>i zi / e zezë</td></tr><tr><td class="ar">أَزْرَقُ / زَرْقَاءُ</td><td>i kaltër / e kaltër</td></tr></table>`,
ex:[{p:'“Sa kushton kjo këmishë?”',o:['بِكَمْ هَذَا الْقَمِيصُ؟','كَمْ هَذَا الْقَمِيصُ؟','بِكَمْ هَذِهِ الْقَمِيصُ؟','مَا هَذَا الْقَمِيصُ؟'],ar:1},{p:'“Pesë libra”',o:['خَمْسَةُ كُتُبٍ','خَمْسُ كُتُبٍ','خَمْسَةُ كِتَابٍ','كُتُبٌ خَمْسَةٌ'],ar:1},{p:'“Katër mollë” (تُفَّاحَةٌ është femërore)',o:['أَرْبَعُ تُفَّاحَاتٍ','أَرْبَعَةُ تُفَّاحَاتٍ','أَرْبَعُ تُفَّاحَةٍ','تُفَّاحَاتٌ أَرْبَعٌ'],ar:1},{p:'Pas كَمْ emri vjen në:',o:['Njëjës','Shumës','Dyjës','Si të duash']},{p:'“Një veturë e zezë”',o:['سَيَّارَةٌ سَوْدَاءُ','سَيَّارَةٌ أَسْوَدُ','سَيَّارَةٌ سَوْدَاءٌ','سَوْدَاءُ سَيَّارَةٌ'],ar:1},{p:'ثَمَانِيَةٌ është numri:',o:['8','6','3','9']},{p:'“Kjo është e lirë.”',o:['هَذَا رَخِيصٌ','هَذَا غَالٍ','هَذَا جَدِيدٌ','هَذَا كَبِيرٌ'],ar:1}]},
