A:[['الْجَوُّ','Moti','el-xhevvu'],['حَارٌّ','I nxehtë','hārrun'],['بَارِدٌ','I ftohtë','bāridun'],['مُعْتَدِلٌ','I butë','mu‘tedilun'],['مَطَرٌ','Shi','matarun'],['ثَلْجٌ','Borë','theljun'],['شَمْسٌ','Diell','shemsun'],['رِيَاحٌ','Erëra','rijāhun'],['غُيُومٌ','Re','gujūmun'],['دَرَجَةُ الْحَرَارَةِ','Temperatura','derexhetu l-harārah'],['الرَّبِيعُ','Pranvera','er-rabī‘u'],['الصَّيْفُ','Vera','es-sajfu'],['الْخَرِيفُ','Vjeshta','el-harīfu'],['الشِّتَاءُ','Dimri','esh-shitā’u'],['فُصُولُ السَّنَةِ','Stinët e vitit','fusūlu s-seneh']],
B:[['كَانَ','Ishte','kāne'],['صَارَ','U bë','sāra'],['لَيْسَ','Nuk është','lejse'],['قَلِيلًا','Pak','kalīlen'],['مِظَلَّةٌ','Ombrellë','midhal-letun'],['مِعْطَفٌ','Pallto','mi‘tafun'],['السَّمَاءُ','Qielli','es-semā’u'],['صَافٍ','I kthjellët','sāfin'],['الْبَحْرُ','Deti','el-bahru'],['الْجَبَلُ','Mali','el-xhebelu'],['يَنْزِلُ','Bie, zbret','jenzilu'],['كَيْفَ الْجَوُّ؟','Si është moti?','kejfe l-xhevvu'],['فِي الْخَارِجِ','Jashtë','fi l-hārixh'],['أُحِبُّ','Dua, më pëlqen','uhibbu']],
D1:{t:'Si është moti sot?',l:[['Halidi','كَيْفَ الْجَوُّ الْيَوْمَ يَا عَلِيُّ؟','Si është moti sot, o Ali?'],['Aliu','الْجَوُّ بَارِدٌ جِدًّا، وَفِي السَّمَاءِ غُيُومٌ.','Moti është shumë i ftohtë dhe në qiell ka re.'],['Halidi','هَلْ يَنْزِلُ الْمَطَرُ؟','A bie shi?'],['Aliu','نَعَمْ، يَنْزِلُ الْمَطَرُ الْآنَ. خُذْ مِظَلَّةً وَمِعْطَفًا.','Po, tani po bie shi. Merr ombrellë dhe pallto.'],['Halidi','وَأَمْسِ كَانَ الْجَوُّ جَمِيلًا!','Kurse dje moti ishte i bukur!'],['Aliu','نَعَمْ، أَمْسِ كَانَتِ السَّمَاءُ صَافِيَةً، وَكَانَتِ الشَّمْسُ حَارَّةً.','Po, dje qielli ishte i kthjellët dhe dielli ishte i nxehtë.'],['Halidi','الْجَوُّ فِي الشِّتَاءِ يَتَغَيَّرُ كَثِيرًا.','Në dimër moti ndryshon shumë.']],
q:[{p:'Si është moti sot?',o:['Shumë i ftohtë','I nxehtë','I butë','I thatë']},{p:'Çfarë duhet të marrë Halidi?',o:['Ombrellë dhe pallto','Kapelë','Ujë','Libër']},{p:'Si ishte moti dje?',o:['I bukur','Me shi','Me borë','I ftohtë']},{p:'Në cilën stinë janë?',o:['Në dimër','Në verë','Në pranverë','Në vjeshtë']}]},
D2:{t:'Stina që më pëlqen',l:[['Lejla','مَاذَا تُحِبِّينَ يَا مَرْيَمُ: الصَّيْفَ أَمِ الشِّتَاءَ؟','Çfarë të pëlqen, o Merjem: vera apo dimri?'],['Merjemi','أُحِبُّ الرَّبِيعَ. الْجَوُّ فِيهِ مُعْتَدِلٌ وَجَمِيلٌ.','Më pëlqen pranvera. Moti në të është i butë dhe i bukur.'],['Lejla','أَنَا أُحِبُّ الصَّيْفَ، لِأَنِّي أَذْهَبُ إِلَى الْبَحْرِ.','Mua më pëlqen vera, sepse shkoj në det.'],['Merjemi','وَلَكِنَّ الصَّيْفَ حَارٌّ جِدًّا عِنْدَنَا.','Por te ne vera është shumë e nxehtë.'],['Lejla','وَفِي كُوسُوفُو الشِّتَاءُ بَارِدٌ، وَيَنْزِلُ الثَّلْجُ.','Kurse në Kosovë dimri është i ftohtë dhe bie borë.'],['Merjemi','مَا شَاءَ اللَّهُ! أُرِيدُ أَنْ أَرَى الثَّلْجَ.','Mashallah! Dua ta shoh borën.']],
q:[{p:'Cila stinë i pëlqen Merjemes?',o:['Pranvera','Vera','Dimri','Vjeshta']},{p:'Pse i pëlqen Lejlës vera?',o:['Shkon në det','Bie borë','Shkon në mal','Nuk ka shkollë']},{p:'Si është dimri në Kosovë?',o:['I ftohtë, me borë','I nxehtë','Me shumë diell','I butë']},{p:'Çfarë dëshiron të shohë Merjemi?',o:['Borën','Detin','Diellin','Malin']}]},
G:{t:'كَانَ: “ishte”, لَيْسَ dhe صَارَ',h:`<p>Fjalia emërore nuk ka folje “është”: <span class="ar">الْجَوُّ بَارِدٌ</span>. Për të shkuarën përdoret <span class="ar">كَانَ</span> (ishte). Kujdes: kallëzuesi pas tij merr fundoren <b>-a / -an</b>:</p>
<table><tr><td class="ar">الْجَوُّ جَمِيلٌ</td><td>moti është i bukur</td></tr><tr><td class="ar">كَانَ الْجَوُّ جَمِيلًا</td><td>moti ishte i bukur</td></tr><tr><td class="ar">كَانَتِ السَّمَاءُ صَافِيَةً</td><td>qielli ishte i kthjellët (femërore: كَانَتْ)</td></tr></table>
<h3>كَانَ sipas vetave</h3><table><tr><td class="ar">كُنْتُ</td><td>unë isha</td></tr><tr><td class="ar">كُنْتَ / كُنْتِ</td><td>ti ishe</td></tr><tr><td class="ar">كَانَ / كَانَتْ</td><td>ai / ajo ishte</td></tr><tr><td class="ar">كُنَّا</td><td>ne ishim</td></tr><tr><td class="ar">كَانُوا</td><td>ata ishin</td></tr></table>
<h3>Si كَانَ: لَيْسَ dhe صَارَ</h3><table><tr><td class="ar">لَيْسَ الْجَوُّ حَارًّا</td><td>moti nuk është i nxehtë</td></tr><tr><td class="ar">صَارَ الْجَوُّ بَارِدًا</td><td>moti u bë i ftohtë</td></tr></table>
<p class="note">Stinët: <span class="ar">الرَّبِيعُ، الصَّيْفُ، الْخَرِيفُ، الشِّتَاءُ</span>.</p>`,
ex:[{p:'“Moti ishte i nxehtë.”',o:['كَانَ الْجَوُّ حَارًّا','كَانَ الْجَوُّ حَارٌّ','الْجَوُّ كَانَ حَارٌّ','كَانَتِ الْجَوُّ حَارًّا'],ar:1},{p:'“Unë isha në shtëpi.”',o:['كُنْتُ فِي الْبَيْتِ','كَانَ فِي الْبَيْتِ','كُنَّا فِي الْبَيْتِ','كَانَتْ فِي الْبَيْتِ'],ar:1},{p:'“Moti nuk është i ftohtë.”',o:['لَيْسَ الْجَوُّ بَارِدًا','لَا الْجَوُّ بَارِدٌ','لَمْ الْجَوُّ بَارِدٌ','لَيْسَ الْجَوُّ بَارِدٌ'],ar:1},{p:'Pas كَانَ, kallëzuesi merr:',o:['Fundoren -a (-an)','Fundoren -u (-un)','Fundoren -i (-in)','Nuk ndryshon']},{p:'الشِّتَاءُ është:',o:['Dimri','Vera','Pranvera','Vjeshta']},{p:'“Ne ishim në det.”',o:['كُنَّا فِي الْبَحْرِ','كُنْتُمْ فِي الْبَحْرِ','كَانُوا فِي الْبَحْرِ','كُنْتُ فِي الْبَحْرِ'],ar:1},{p:'“Bie shi.”',o:['يَنْزِلُ الْمَطَرُ','يَنْزِلُ الثَّلْجُ','الشَّمْسُ حَارَّةٌ','الْجَوُّ صَافٍ'],ar:1}]},
