{n:16,ar:'الْعُطْلَةُ',sq:'Pushimet',
A:[['الْإِجَازَةُ','Leja, pushimet','el-ixhāzetu'],['شَاطِئٌ','Plazh','shāti’un'],['رَمْلٌ','Rërë','remlun'],['خَيْمَةٌ','Tendë','hajmetun'],['غَابَةٌ','Pyll','gābetun'],['آلَةُ التَّصْوِيرِ','Aparat fotografik','āletu t-tasvīr'],['ذِكْرَيَاتٌ','Kujtime','dhikrajātun'],['أَقَارِبُ','Të afërm','ekāribu'],['عَامٌ','Vit','‘āmun'],['الشَّهْرُ','Muaji','esh-shehru'],['يَزُورُ','Viziton','jezūru'],['زُرْنَا','Vizituam','zurnā'],['قَضَى','Kaloi (kohë)','kadā'],['يَسْتَرِيحُ','Pushon, çlodhet','jesterīhu'],['رَائِعٌ','Mahnitës','rā’i‘un']],
B:[['الْأَوَّلُ','I pari','el-evvelu'],['الثَّانِي','I dyti','eth-thānī'],['الثَّالِثُ','I treti','eth-thālithu'],['الرَّابِعُ','I katërti','er-rābi‘u'],['الْخَامِسُ','I pesti','el-hāmisu'],['السَّادِسُ','I gjashti','es-sādisu'],['السَّابِعُ','I shtati','es-sābi‘u'],['الثَّامِنُ','I teti','eth-thāminu'],['التَّاسِعُ','I nënti','et-tāsi‘u'],['الْعَاشِرُ','I dhjeti','el-‘āshiru'],['الْمَاضِي','I kaluar','el-mādī'],['الْقَادِمُ','I ardhshëm','el-kādimu'],['الْأَخِيرُ','I fundit','el-ehīru'],['فِي الْبِدَايَةِ','Në fillim','fi l-bidājeh']],
D1:{t:'Ku i kalove pushimet?',l:[['Zejdi','أَيْنَ قَضَيْتَ الْعُطْلَةَ يَا بِلَالُ؟','Ku i kalove pushimet, o Bilal?'],['Bilali','ذَهَبْتُ مَعَ أُسْرَتِي إِلَى الْبَحْرِ فِي أَلْبَانِيَا.','Shkova me familjen në det, në Shqipëri.'],['Zejdi','كَمْ يَوْمًا بَقِيتُمْ هُنَاكَ؟','Sa ditë qëndruat atje?'],['Bilali','بَقِينَا عَشَرَةَ أَيَّامٍ. سَبَحْنَا كُلَّ يَوْمٍ، وَزُرْنَا مَدِينَةً قَدِيمَةً.','Qëndruam dhjetë ditë. Notuam çdo ditë dhe vizituam një qytet të vjetër.'],['Zejdi','رَائِعٌ! وَمَاذَا سَتَفْعَلُ فِي الْعُطْلَةِ الْقَادِمَةِ؟','Mahnitëse! Po në pushimet e ardhshme çfarë do të bësh?'],['Bilali','سَأَزُورُ جَدَّتِي فِي الْقَرْيَةِ، وَسَأَقْرَأُ كُتُبًا كَثِيرَةً.','Do ta vizitoj gjyshen në fshat dhe do të lexoj shumë libra.'],['Zejdi','وَأَنَا سَأُسَافِرُ إِلَى الْعُمْرَةِ إِنْ شَاءَ اللَّهُ.','Kurse unë do të udhëtoj për umre, inshallah.']],
q:[{p:'Ku shkoi Bilali?',o:['Në det, në Shqipëri','Në mal','Në Mekë','Te gjyshja']},{p:'Sa ditë qëndruan?',o:['Dhjetë','Shtatë','Pesë','Tri']},{p:'Çfarë do të bëjë Bilali në pushimet e ardhshme?',o:['Do ta vizitojë gjyshen','Do të shkojë në det','Do të punojë','Do të shkojë për umre']},{p:'Çfarë do të bëjë Zejdi?',o:['Do të shkojë për umre','Do të notojë','Do të lexojë','Do të punojë']}]},
D2:{t:'Fotografitë e pushimeve',l:[['Merjemi','انْظُرِي يَا سَارَةُ، هَذِهِ صُوَرُ الْعُطْلَةِ.','Shiko, o Sara, këto janë fotografitë e pushimeve.'],['Sara','مَا أَجْمَلَهَا! أَيْنَ هَذِهِ الصُّورَةُ الْأُولَى؟','Sa të bukura! Ku është kjo fotografi e parë?'],['Merjemi','هَذِهِ فِي الْيَوْمِ الْأَوَّلِ، فِي الْغَابَةِ. نِمْنَا فِي خَيْمَةٍ.','Kjo është në ditën e parë, në pyll. Fjetëm në tendë.'],['Sara','وَهَذِهِ الصُّورَةُ الثَّانِيَةُ؟','Po kjo fotografi e dytë?'],['Merjemi','هَذِهِ عَلَى الشَّاطِئِ فِي الْيَوْمِ الثَّالِثِ. الرَّمْلُ أَبْيَضُ، وَالْبَحْرُ أَزْرَقُ.','Kjo është në plazh, në ditën e tretë. Rëra është e bardhë dhe deti i kaltër.'],['Sara','عُطْلَةٌ رَائِعَةٌ! أَنَا قَضَيْتُ الْعُطْلَةَ فِي الْبَيْتِ مَعَ أَقَارِبِي.','Pushime mahnitëse! Unë i kalova pushimet në shtëpi me të afërmit.'],['Merjemi','هَذَا جَمِيلٌ أَيْضًا. فِي الْعَامِ الْقَادِمِ نُسَافِرُ مَعًا إِنْ شَاءَ اللَّهُ!','Edhe kjo është bukur. Vitin e ardhshëm udhëtojmë bashkë, inshallah!']],
q:[{p:'Ku ishin në ditën e parë?',o:['Në pyll','Në plazh','Në qytet','Në shtëpi']},{p:'Ku fjetën?',o:['Në tendë','Në hotel','Në shtëpi','Te gjyshja']},{p:'Si është rëra?',o:['E bardhë','E zezë','E verdhë','E kuqe']},{p:'Ku i kaloi Sara pushimet?',o:['Në shtëpi me të afërmit','Në det','Në pyll','Në Mekë']}]},
G:{t:'Tri kohët bashkë dhe numrat rreshtorë',h:`<p>Në këtë njësi i përsërisim tri kohët e foljes:</p>
<table><tr><td class="ar">زُرْتُ جَدَّتِي</td><td>e vizitova gjyshen (e shkuara)</td></tr><tr><td class="ar">أَزُورُ جَدَّتِي</td><td>e vizitoj gjyshen (e tashmja)</td></tr><tr><td class="ar">سَأَزُورُ جَدَّتِي</td><td>do ta vizitoj gjyshen (e ardhmja)</td></tr></table>
<h3>Numrat rreshtorë</h3><table><tr><td class="ar">الْأَوَّلُ / الْأُولَى</td><td>i pari / e para</td></tr><tr><td class="ar">الثَّانِي / الثَّانِيَةُ</td><td>i dyti / e dyta</td></tr><tr><td class="ar">الثَّالِثُ / الثَّالِثَةُ</td><td>i treti / e treta</td></tr><tr><td class="ar">الرَّابِعُ … الْعَاشِرُ</td><td>i katërti … i dhjeti</td></tr></table>
<p>Rreshtori vjen pas emrit si mbiemër: <span class="ar">الْيَوْمُ الْأَوَّلُ</span> (dita e parë), <span class="ar">الصُّورَةُ الثَّانِيَةُ</span> (fotografia e dytë).</p>
<h3>E kaluara dhe e ardhmja</h3><table><tr><td class="ar">الْأُسْبُوعَ الْمَاضِيَ</td><td>javën e kaluar</td></tr><tr><td class="ar">فِي الْعَامِ الْقَادِمِ</td><td>vitin e ardhshëm</td></tr></table>
<p class="note">Me këtë njësi mbaron Niveli 1 (libri i parë). Testi i nivelit përfshin të 16 njësitë.</p>`,
ex:[{p:'“Do ta vizitoj gjyshen.”',o:['سَأَزُورُ جَدَّتِي','زُرْتُ جَدَّتِي','أَزُورُ جَدَّتِي','زَارَتْ جَدَّتِي'],ar:1},{p:'“Vizituam një qytet të vjetër.” Cila është folja?',o:['زُرْنَا','نَزُورُ','سَنَزُورُ','زَارُوا'],ar:1},{p:'“Dita e parë”',o:['الْيَوْمُ الْأَوَّلُ','الْيَوْمُ الْأُولَى','الْأَوَّلُ يَوْمٌ','يَوْمٌ الْأَوَّلُ'],ar:1},{p:'الثَّالِثَةُ do të thotë:',o:['E treta','I treti','Tre','Tri herë']},{p:'“Javën e kaluar”',o:['الْأُسْبُوعَ الْمَاضِيَ','الْأُسْبُوعَ الْقَادِمَ','هَذَا الْأُسْبُوعَ','كُلَّ أُسْبُوعٍ'],ar:1},{p:'Cila fjali është në të ardhmen?',o:['سَنُسَافِرُ مَعًا','سَافَرْنَا مَعًا','نُسَافِرُ الْآنَ','مَا سَافَرْنَا'],ar:1},{p:'“Qëndruam dhjetë ditë.”',o:['بَقِينَا عَشَرَةَ أَيَّامٍ','بَقِينَا عَشْرَ أَيَّامٍ','بَقِينَا عَشَرَةَ يَوْمٍ','نَبْقَى عَشَرَةَ أَيَّامٍ'],ar:1}]},
build:[['Shkova në det me familjen.',['ذَهَبْتُ','إِلَى','الْبَحْرِ','مَعَ','أُسْرَتِي']],['Do ta vizitoj gjyshen.',['سَأَزُورُ','جَدَّتِي']],['Kjo është fotografia e parë.',['هَذِهِ','الصُّورَةُ','الْأُولَى']],['Fjetëm në tendë.',['نِمْنَا','فِي','خَيْمَةٍ']],['Pushime mahnitëse!',['عُطْلَةٌ','رَائِعَةٌ']]],
say:[['Pyet: Ku i kalove pushimet?','أَيْنَ قَضَيْتَ الْعُطْلَةَ؟'],['Thuaj: Shkova në det.','ذَهَبْتُ إِلَى الْبَحْرِ'],['Thuaj: Do të udhëtoj vitin e ardhshëm.','سَأُسَافِرُ فِي الْعَامِ الْقَادِمِ'],['Numëro: i pari, i dyti, i treti.','الْأَوَّلُ، الثَّانِي، الثَّالِثُ'],['Thuaj: Pushimet ishin mahnitëse.','كَانَتِ الْعُطْلَةُ رَائِعَةً']]}

